"""configloader — implement parse_config and get per README.md."""


def _coerce(value):
    """Coerce a raw value string to bool, int, float, or str."""
    if len(value) >= 2 and value.startswith('"') and value.endswith('"'):
        return value[1:-1]

    lowered = value.lower()
    if lowered in ("true", "false"):
        return lowered == "true"

    # Require a digit so "nan"/"inf" stay strings.
    if any(char.isdigit() for char in value):
        try:
            return int(value)
        except ValueError:
            pass
        try:
            return float(value)
        except ValueError:
            pass

    return value


def parse_config(text):
    config = {"": {}}
    section = ""

    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith("#") or line.startswith(";"):
            continue

        if line.startswith("[") and line.endswith("]"):
            section = line[1:-1].strip()
            config.setdefault(section, {})
            continue

        if "=" not in line:
            continue

        key, _, value = line.partition("=")
        config[section][key.strip()] = _coerce(value.strip())

    return config


def get(config, dotted, default=None):
    section, _, key = dotted.rpartition(".")
    return config.get(section, {}).get(key, default)

